.cart-count {
    font-size: 0.875rem;
    font-weight: 600;
    color: var(--color-accent-1);
}

/* ===========================
   BUTTONS
   =========================== */
.btn {
    padding: 0.875rem 1.75rem;
    border: none;
    border-radius: var(--border-radius);
    font-size: 1rem;
    font-weight: 600;
    cursor: pointer;
    transition: var(--transition);
    text-transform: uppercase;
    letter-spacing: 0.05em;
}

.btn-primary {
    background: linear-gradient(135deg, var(--color-accent-1), var(--color-accent-2));
    color: white;
}

.btn-primary:hover {
    transform: translateY(-2px);
    box-shadow: 0 10px 30px rgba(139, 92, 246, 0.3);
}

.btn-secondary {
    background-color: var(--color-bg-tertiary);
    color: var(--color-text-primary);
    border: 1px solid var(--color-border);
}

.btn-secondary:hover {
    background-color: var(--color-accent-1);
    border-color: var(--color-accent-1);
}

.btn-add-cart {
    background-color: transparent;
    color: var(--color-accent-1);
    border: 1px solid var(--color-accent-1);
    padding: 0.5rem 1rem;
    border-radius: 6px;
    cursor: pointer;
    font-weight: 600;
    font-size: 0.875rem;
    transition: var(--transition);
}

.btn-add-cart:hover {
    background-color: var(--color-accent-1);
    color: white;
}

/* ===========================
   HERO SECTION
   =========================== */
.hero {
    background: linear-gradient(135deg, var(--color-bg-secondary) 0%, var(--color-bg-tertiary) 100%);
    min-height: 500px;
    display: flex;
    align-items: center;
    justify-content: center;
    text-align: center;
    position: relative;
    overflow: hidden;
}

.hero::before {
    content: '';
    position: absolute;
    top: -50%;
    right: -10%;
    width: 500px;
    height: 500px;
    background: radial-gradient(circle, rgba(139, 92, 246, 0.1), transparent 70%);
    border-radius: 50%;
}

.hero::after {
    content: '';
    position: absolute;
    bottom: -20%;
    left: -5%;
    width: 400px;
    height: 400px;
    background: radial-gradient(circle, rgba(59, 130, 246, 0.1), transparent 70%);
    border-radius: 50%;
}

.hero-content {
    position: relative;
    z-index: 1;
    max-width: 600px;
}

.hero-content h2 {
    margin-bottom: var(--spacing-md);
    font-size: 3.5rem;
    line-height: 1.1;
}

.hero-content p {
    font-size: 1.25rem;
    margin-bottom: var(--spacing-lg);
    color: var(--color-text-secondary);
}

.hero .btn {
    margin-top: var(--spacing-lg);
}

/* ===========================
   SECTION TITLES
   =========================== */
.section-title {
    text-align: center;
    margin-bottom: var(--spacing-md);
    font-size: 2.5rem;
}

.section-subtitle {
    text-align: center;
    color: var(--color-text-tertiary);
    margin-bottom: var(--spacing-xl);
    font-size: 1.125rem;
}

/* ===========================
   FEATURED PRODUCTS
   =========================== */
.featured-section {
    background-color: var(--color-bg-primary);
}

.products-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
    gap: var(--spacing-lg);
    margin-top: var(--spacing-xl);
}

.product-card {
    background-color: var(--color-bg-secondary);
    border: 1px solid var(--color-border);
    border-radius: var(--border-radius);
    overflow: hidden;
    transition: var(--transition);
}

.product-card:hover {
    border-color: var(--color-accent-1);
    transform: translateY(-8px);
    box-shadow: 0 20px 40px rgba(139, 92, 246, 0.2);
}

.product-image {
    width: 100%;
    height: 250px;
    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
}

.product-info {
    padding: var(--spacing-lg);
}

.product-info h3 {
    margin-bottom: var(--spacing-xs);
    font-size: 1.25rem;
}

.product-category {
    color: var(--color-text-tertiary);
    font-size: 0.875rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    margin-bottom: var(--spacing-md);
}

.product-footer {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding-top: var(--spacing-md);
    border-top: 1px solid var(--color-border);
}

.price {
    font-size: 1.5rem;
    font-weight: 700;
    background: linear-gradient(135deg, var(--color-accent-1), var(--color-accent-2));
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
}

/* ===========================
   DEALS SECTION
   =========================== */
.deals-section {
    background-color: var(--color-bg-secondary);
}

.deals-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
    gap: var(--spacing-lg);
    margin-top: var(--spacing-xl);
}

.deal-card {
    background-color: var(--color-bg-tertiary);
    border-radius: var(--border-radius);
    overflow: hidden;
    transition: var(--transition);
    position: relative;
}

.deal-card:hover {
    transform: scale(1.05);
    box-shadow: 0 20px 50px rgba(139, 92, 246, 0.3);
}

.deal-card.featured-deal {
    grid-column: span 1;
}

@media (min-width: 1024px) {
    .deal-card.featured-deal {
        grid-column: span 1;
        transform: scale(1);
    }

    .deals-grid {
        grid-template-columns: repeat(3, 1fr);
    }
}

.deal-badge {
    position: absolute;
    top: 1rem;
    right: 1rem;
    background: linear-gradient(135deg, var(--color-accent-3), var(--color-accent-1));
    color: white;
    padding: 0.5rem 1rem;
    border-radius: 50px;
    font-weight: 700;
    z-index: 10;
    font-size: 1.1rem;
}

.deal-image {
    width: 100%;
    height: 250px;
    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
}

.deal-info {
    padding: var(--spacing-lg);
    text-align: center;
}

.deal-info h3 {
    margin-bottom: var(--spacing-md);
    font-size: 1.25rem;
}

.original-price {
    color: var(--color-text-tertiary);
    text-decoration: line-through;
    font-size: 0.95rem;
    margin-bottom: var(--spacing-xs);
}

.deal-price {
    font-size: 2rem;
    font-weight: 700;
    color: var(--color-accent-3);
    margin-bottom: var(--spacing-lg);
}

.deal-card .btn {
    width: 100%;
}

/* ===========================
   EDITORIAL SECTION
   =========================== */
.editorial-section {
    background-color: var(--color-bg-primary);
}

.editorial-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
    gap: var(--spacing-lg);
    margin-top: var(--spacing-xl);
}

.editorial-card {
    background-color: var(--color-bg-secondary);
    border-radius: var(--border-radius);
    overflow: hidden;
    transition: var(--transition);
    display: flex;
    flex-direction: column;
}

.editorial-card:hover {
    transform: translateY(-10px);
}

.editorial-card.large {
    grid-column: span 1;
}

@media (min-width: 1024px) {
    .editorial-grid {
        grid-template-columns: repeat(3, 1fr);
    }

    .editorial-card.large {
        grid-column: span 2;
        flex-direction: row;
    }

    .editorial-card.large .article-image {
        min-height: auto;
        width: 50%;
    }

    .editorial-card.large .article-content {
        width: 50%;
    }
}

.article-image {
    width: 100%;
    min-height: 200px;
    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
}

.article-content {
    padding: var(--spacing-lg);
    display: flex;
    flex-direction: column;
    flex: 1;
}

.article-date {
    color: var(--color-text-tertiary);
    font-size: 0.875rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    margin-bottom: var(--spacing-md);
}

.editorial-card h3 {
    margin-bottom: var(--spacing-md);
    line-height: 1.3;
}

.editorial-card p {
    flex: 1;
    margin-bottom: var(--spacing-md);
    color: var(--color-text-secondary);
}

.read-more {
    color: var(--color-accent-1);
    font-weight: 600;
    display: inline-block;
    position: relative;
}

.read-more::after {
    content: '';
    position: absolute;
    bottom: -2px;
    left: 0;
    width: 0;
    height: 2px;
    background-color: var(--color-accent-1);
    transition: var(--transition);
}

.read-more:hover::after {
    width: 100%;
}

/* ===========================
   NEWSLETTER SECTION
   =========================== */
.newsletter-section {
    background: linear-gradient(135deg, var(--color-bg-secondary) 0%, var(--color-bg-tertiary) 100%);
}

.newsletter-content {
    text-align: center;
    max-width: 600px;
}

.newsletter-content h2 {
    margin-bottom: var(--spacing-md);
}

.newsletter-content p {
    margin-bottom: var(--spacing-lg);
    color: var(--color-text-secondary);
}

.newsletter-form {
    display: flex;
    gap: var(--spacing-sm);
    flex-direction: row;
}

.newsletter-form input {
    flex: 1;
    padding: 0.875rem 1.25rem;
    background-color: var(--color-bg-primary);
    border: 1px solid var(--color-border);
    border-radius: var(--border-radius);
    color: var(--color-text-primary);
    font-size: 1rem;
}

.newsletter-form input::placeholder {
    color: var(--color-text-tertiary);
}

.newsletter-form input:focus {
    outline: none;
    border-color: var(--color-accent-1);
    box-shadow: 0 0 0 3px rgba(139, 92, 246, 0.1);
}

.newsletter-form button {
    white-space: nowrap;
}

/* ===========================
   FOOTER
   =========================== */
.footer {
    background-color: var(--color-bg-secondary);
    border-top: 1px solid var(--color-border);
    padding: var(--spacing-2xl) 0;
}

.footer-content {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: var(--spacing-xl);
    margin-bottom: var(--spacing-2xl);
}

.footer-section h4 {
    margin-bottom: var(--spacing-md);
    font-size: 1rem;
    text-transform: uppercase;
    letter-spacing: 1px;
}

.footer-section ul {
    list-style: none;
}

.footer-section li {
    margin-bottom: var(--spacing-sm);
}

.footer-section a {
    color: var(--color-text-tertiary);
    transition: var(--transition);
}

.footer-section a:hover {
    color: var(--color-accent-1);
}

.footer-bottom {
    border-top: 1px solid var(--color-border);
    padding-top: var(--spacing-lg);
    display: flex;
    justify-content: space-between;
    align-items: center;
    flex-wrap: wrap;
    gap: var(--spacing-lg);
    color: var(--color-text-tertiary);
}

.footer-links {
    display: flex;
    gap: var(--spacing-lg);
}

/* ===========================
   CART NOTIFICATION
   =========================== */
.cart-notification {
    position: fixed;
    bottom: 2rem;
    right: 2rem;
    background-color: var(--color-accent-1);
    color: white;
    padding: 1rem 1.5rem;
    border-radius: var(--border-radius);
    opacity: 0;
    transform: translateY(20px);
    pointer-events: none;
    transition: var(--transition);
    z-index: 1000;
    font-weight: 600;
}

.cart-notification.show {
    opacity: 1;
    transform: translateY(0);
    pointer-events: auto;
}

/* ===========================
   RESPONSIVE DESIGN
   =========================== */
@media (max-width: 768px) {
    .container {
        padding: 0 var(--spacing-md);
    }

    h1 {
        font-size: 2rem;
    }

    h2 {
        font-size: 1.75rem;
    }

    .nav-menu {
        gap: var(--spacing-md);
    }

    .hero-content h2 {
        font-size: 2.25rem;
    }

    .hero-content p {
        font-size: 1rem;
    }

    .products-grid,
    .deals-grid {
        grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
        gap: var(--spacing-md);
    }

    .editorial-grid {
        grid-template-columns: 1fr;
    }

    .editorial-card.large {
        grid-column: span 1;
        flex-direction: column;
    }

    .editorial-card.large .article-image {
        width: 100%;
    }

    .editorial-card.large .article-content {
        width: 100%;
    }

    .newsletter-form {
        flex-direction: column;
    }

    .newsletter-form input {
        width: 100%;
    }

    .footer-bottom {
        flex-direction: column;
        text-align: center;
    }

    .footer-links {
        flex-direction: column;
        gap: var(--spacing-sm);
    }
}

@media (max-width: 480px) {
    :root {
        --spacing-lg: 1.5rem;
        --spacing-xl: 2rem;
        --spacing-2xl: 2.5rem;
    }

    .nav-menu {
        gap: var(--spacing-sm);
        font-size: 0.9rem;
    }

    .hero {
        min-height: 400px;
    }

    .hero-content h2 {
        font-size: 1.75rem;
    }

    section {
        padding: var(--spacing-lg) 0;
    }

    .btn {
        padding: 0.75rem 1.25rem;
        font-size: 0.9rem;
    }
}
