    display: flex;
    align-items: center;
    justify-content: center;
    text-align: center;
    position: relative;
    overflow: hidden;
}

.hero::before {
    content: '';
    position: absolute;
    top: -50%;
    right: -10%;
    width: 500px;
    height: 500px;
    background: radial-gradient(circle, rgba(139, 92, 246, 0.1), transparent 70%);
    border-radius: 50%;
}

.hero::after {
    content: '';
    position: absolute;
    bottom: -20%;
    left: -5%;
    width: 400px;
    height: 400px;
    background: radial-gradient(circle, rgba(59, 130, 246, 0.1), transparent 70%);
    border-radius: 50%;
}

.hero-content {
    position: relative;
    z-index: 1;
    max-width: 600px;
}

.hero-content h2 {
    margin-bottom: var(--spacing-md);
    font-size: 3.5rem;
    line-height: 1.1;
}

.hero-content p {
    font-size: 1.25rem;
    margin-bottom: var(--spacing-lg);
    color: var(--color-text-secondary);
}

.hero .btn {
    margin-top: var(--spacing-lg);
}

