        min-height: auto;
        width: 50%;
    }

    .editorial-card.large .article-content {
        width: 50%;
    }
}

.article-image {
    width: 100%;
    min-height: 200px;
    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
