    font-weight: 600;
    line-height: 1.2;
}

h1 {
    font-size: 3rem;
}

h2 {
    font-size: 2.5rem;
}

h3 {
    font-size: 1.5rem;
}

p {
    color: var(--color-text-secondary);
    margin-bottom: var(--spacing-md);
}

a {
    color: var(--color-text-primary);
    text-decoration: none;
    transition: var(--transition);
}

a:hover {
    color: var(--color-accent-1);
}

/* ===========================
   CONTAINER & LAYOUT
   =========================== */
.container {
    max-width: 1280px;
    margin: 0 auto;
    padding: 0 var(--spacing-lg);
}

