document.addEventListener('DOMContentLoaded', function() {
    const cartButton = document.querySelector('.nav-cart');

    cartButton.addEventListener('click', function() {
        if (cart.length === 0) {
            showCartNotification('Cart is empty');
        } else {
            const total = cart.reduce((sum, item) => sum + item.price, 0).toFixed(2);
            const itemCount = cart.length;
            showCartNotification(`${itemCount} items · Total: $${total}`);
        }
    });

    // Initialize cart count
    updateCartCount();
});

// ===========================
// SMOOTH SCROLLING ENHANCEMENT
// ===========================
document.querySelectorAll('a[href^="#"]').forEach(anchor => {
    anchor.addEventListener('click', function(e) {
        const href = this.getAttribute('href');
        if (href !== '#' && document.querySelector(href)) {
            e.preventDefault();
            const target = document.querySelector(href);
            target.scrollIntoView({
                behavior: 'smooth',
                block: 'start'
            });
        }
    });
});

// ===========================
// INTERSECTION OBSERVER FOR ANIMATIONS
// ===========================
const observerOptions = {
    threshold: 0.1,
    rootMargin: '0px 0px -50px 0px'
};

const observer = new IntersectionObserver(function(entries) {
    entries.forEach(entry => {
        if (entry.isIntersecting) {
            entry.target.style.opacity = '1';
            entry.target.style.transform = 'translateY(0)';
        }
    });
}, observerOptions);

// Observe product and editorial cards for fade-in animation
document.querySelectorAll('.product-card, .deal-card, .editorial-card').forEach(card => {
    card.style.opacity = '0';
    card.style.transform = 'translateY(20px)';
    card.style.transition = 'opacity 0.6s ease-out, transform 0.6s ease-out';
    observer.observe(card);
});

